extends Node3D

@onready var grid_map: GridMap = get_node("GridMap")

func build() -> void:
	# Clear existing cells
	grid_map.clear()

	# Build MeshLibrary
	var mesh_library = MeshLibrary.new()
	var item_ids = [0, 1, 2]
	var colors = [Color.RED, Color.GREEN, Color.BLUE]

	for i in range(item_ids.size()):
		var item_id = item_ids[i]
		var mesh = BoxMesh.new()
		mesh.size = Vector3(1, 1, 1)

		var mat = StandardMaterial3D.new()
		mat.albedo_color = colors[i]
		mesh.surface_set_material(0, mat)

		mesh_library.create_item(item_id)
		mesh_library.set_item_mesh(item_id, mesh)
		mesh_library.set_item_name(item_id, "Item" + str(item_id))

	grid_map.mesh_library = mesh_library

	# Load level data
	var file = FileAccess.open("res://data/level.json", FileAccess.READ)
	if not file:
		push_error("Failed to open level.json")
		return

	var json_text = file.get_as_text()
	file.close()

	var data = JSON.parse_string(json_text)
	if typeof(data) != TYPE_DICTIONARY:
		push_error("Invalid JSON format")
		return

	if not data.has("cells"):
		push_error("JSON missing 'cells' key")
		return

	for cell in data["cells"]:
		var item_id = cell["id"]
		var x = cell["x"]
		var y = cell["y"]
		var z = cell["z"]
		place(item_id, x, y, z)

func place(item_id: int, gx: int, gy: int, gz: int) -> void:
	grid_map.set_cell_item(Vector3i(gx, gy, gz), item_id)

func remove(gx: int, gy: int, gz: int) -> void:
	grid_map.set_cell_item(Vector3i(gx, gy, gz), GridMap.INVALID_CELL_ITEM)

func get_item(gx: int, gy: int, gz: int) -> int:
	return grid_map.get_cell_item(Vector3i(gx, gy, gz))
EOF
